def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = paren_string.replace(" ", "")
    groups: List[str] = []
    current = ""
    depth = 0
    for ch in cleaned:
        if ch not in ("(", ")"):
            continue
        current += ch
        if ch == "(":
            depth += 1
        else:  # ch == ")"
            depth -= 1
            if depth < 0:
                raise ValueError("Unbalanced parentheses detected.")
            if depth == 0:
                groups.append(current)
                current = ""
    if depth != 0:
        raise ValueError("Unbalanced parentheses detected at end of string.")
    return groups

def max_value_on_paths(N: int, grid_values: list) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.
    """
    # Validate input
    if N <= 0:
        return 0

    # Build grid (1-indexed)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    INF_NEG = -10**15
    # dp_prev[i1][i2] holds max sum after step s-1 with persons at rows i1,i2
    dp_prev = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Steps count s = i + j, starting from 2 (1+1)
    for s in range(3, 2 * N + 1):
        dp_cur = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, s - N)
        i_max = min(N, s - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = s - i1
            if not (1 <= j1 <= N):
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = s - i2
                if not (1 <= j2 <= N):
                    continue
                add_val = grid[i1][j1]
                if (i1, j1) != (i2, j2):
                    add_val += grid[i2][j2]
                best_prev = INF_NEG
                # Possible previous positions for each path
                for pi1 in (i1, i1 - 1):
                    if pi1 < 1:
                        continue
                    pj1 = (s - 1) - pi1
                    if pj1 < 1 or pj1 > N:
                        continue
                    for pi2 in (i2, i2 - 1):
                        if pi2 < 1:
                            continue
                        pj2 = (s - 1) - pi2
                        if pj2 < 1 or pj2 > N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val
                if best_prev != INF_NEG:
                    dp_cur[i1][i2] = best_prev + add_val
        dp_prev = dp_cur

    return dp_prev[N][N]

