def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication
    signs into the number string `num_str` of length N.
    The string consists only of decimal digits.
    """
    # Sanity checks
    if not num_str:
        return 0
    if N != len(num_str):
        N = len(num_str)
    if K < 0 or K > N - 1:
        return 0
    if K == 0:
        return int(num_str)

    # dp[i][k] = maximum product for the prefix num_str[:i]
    # using exactly k cuts (k+1 segments)
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1  # product of zero numbers is 1 (neutral element)

    for i in range(1, N + 1):
        # No cut before i: whole prefix is one segment
        dp[i][0] = int(num_str[:i])

        # For cuts k = 1..min(K, i-1)
        max_k = min(K, i - 1)
        for k in range(1, max_k + 1):
            best = 0
            # j is the start of the last segment; at least k characters before j
            for j in range(k, i):
                if dp[j][k - 1] == 0:
                    continue
                segment = int(num_str[j:i])
                prod = dp[j][k - 1] * segment
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N][K] if dp[N][K] != 0 else 0

