def count_partitions(n:int, k:int, x:int)->int:
    """
    Count integer partitions of n into k parts each >= x, order doesn't matter.
    """
    # Validate
    if any(not isinstance(v, int) for v in (n,k,x)) or n<0 or k<0 or x<0:
        raise ValueError('Parameters must be non-negative integers')
    if k==0:
        return int(n==0)
    m=n - k*x
    if m<0:
        return 0
    # DP
    dp=[[0]*(k+1) for _ in range(m+1)]
    for j in range(k+1): dp[0][j]=1
    for i in range(1,m+1):
        for j in range(1,k+1):
            dp[i][j]=dp[i][j-1]
            if i>=j:
                dp[i][j]+=dp[i-j][j]
    return dp[m][k]

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.

    :param inorder: str, inorder traversal of unique characters
    :param postorder: str, postorder traversal of the same characters
    :return: str, preorder traversal
    """
    # Basic validation
    if not isinstance(inorder, str) or not isinstance(postorder, str):
        raise TypeError("Both inorder and postorder must be strings.")

    n = len(inorder)
    if n != len(postorder):
        raise ValueError("Inorder and postorder strings must be of the same length.")

    if n == 0:
        return ""

    # Check for duplicate characters in inorder (since elements are unique)
    if len(set(inorder)) != n:
        raise ValueError("Inorder string contains duplicate characters.")
    if set(inorder) != set(postorder):
        raise ValueError("Inorder and postorder contain different sets of characters.")

    # Map each character to its index in inorder for O(1) lookups
    idx_map = {char: i for i, char in enumerate(inorder)}

    def build(in_l: int, in_r: int, post_l: int, post_r: int) -> str:
        if in_l > in_r or post_l > post_r:
            return ""
        # Root is the last element in postorder segment
        root = postorder[post_r]
        if root not in idx_map:
            raise ValueError(f"Character '{root}' from postorder not found in inorder.")
        # Index of root in inorder
        in_root_idx = idx_map[root]
        # Size of left subtree
        left_size = in_root_idx - in_l
        # Build preorder string recursively
        left_pre = build(in_l, in_root_idx - 1, post_l, post_l + left_size - 1)
        right_pre = build(in_root_idx + 1, in_r, post_l + left_size, post_r - 1)
        return root + left_pre + right_pre

    try:
        return build(0, n - 1, 0, n - 1)
    except Exception as e:
        # Catch any unforeseen errors and re-raise as ValueError for clarity
        raise ValueError(f"Failed to reconstruct tree: {e}") from e

