            return "NO ANSWER!"
        if A == B:
            return 0
        from collections import deque
        max_steps = 10
        queue = deque([(A, 0)])
        seen = {A}
        while queue:
            current, steps = queue.popleft()
            if steps >= max_steps:
                continue
            for src, tgt in rules:
                if not isinstance(src, str) or not isinstance(tgt, str):
                    continue
                start = 0
                while True:
                    idx = current.find(src, start)
                    if idx == -1:
                        break
                    new_str = current[:idx] + tgt + current[idx + len(src):]
                    if new_str == B:
                        return steps + 1
                    if new_str not in seen:
                        seen.add(new_str)
                        queue.append((new_str, steps + 1))
                    start = idx + 1
        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

