def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculates the maximum total value of herbs that can be picked within a given time limit
    using a 0/1 knapsack dynamic programming approach.

    :param T: Total time available for picking herbs. Must be a non-negative integer.
    :param M: Number of different herbs in the cave. Must match len(herbs) and be non-negative.
    :param herbs: List of tuples, each containing (time_required, value). Both values must be non-negative integers.
    :return: The maximum total value achievable without exceeding the time limit.
    :raises ValueError: If input arguments are not of the expected type or values are negative.
    """
    # Input validation
    if not isinstance(T, int) or T < 0:
        raise ValueError("T must be a non-negative integer.")
    if not isinstance(M, int) or M < 0:
        raise ValueError("M must be a non-negative integer.")
    if not isinstance(herbs, list):
        raise ValueError("herbs must be a list of tuples.")
    if len(herbs) != M:
        raise ValueError("Length of herbs list must equal M.")
    for idx, herb in enumerate(herbs):
        if (
            not isinstance(herb, tuple)
            or len(herb) != 2
            or not isinstance(herb[0], int)
            or not isinstance(herb[1], int)
            or herb[0] < 0
            or herb[1] < 0
        ):
            raise ValueError(
                f"Herb at index {idx} is invalid. Each herb must be a tuple of two non-negative integers."
            )

    # Initialize DP array where dp[time] is the maximum value achievable with that time.
    dp = [0] * (T + 1)

    for time_needed, value in herbs:
        # Skip herbs that cannot be taken within the time limit
        if time_needed > T:
            continue
        # Traverse times backwards to avoid reuse of the same herb
        for t in range(T, time_needed - 1, -1):
            new_val = dp[t - time_needed] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return dp[T]

def vigenere_decrypt(key, ciphertext):
    if not key.isalpha():
        raise ValueError('Key must contain only alphabetic characters.')
    if not ciphertext.isalpha():
        raise ValueError('Ciphertext must contain only alphabetic characters.')
    if not key:
        raise ValueError('Key cannot be empty.')
    key_lower = key.lower()
    ciphertext_lower = ciphertext.lower()
    plaintext = []
    key_len = len(key_lower)
    for i, ch in enumerate(ciphertext_lower):
        shift = ord(key_lower[i % key_len]) - ord('a')
        decrypted_char = chr((ord(ch) - ord('a') - shift) % 26 + ord('a'))
        plaintext.append(decrypted_char)
    return ''.join(plaintext)

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Handle empty or single-element list
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 2:
        return 0  # Already forms a bitonic sequence

    # Compute Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum removals required
    return n - max_bitonic

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    try:
        heights = list(heights)
    except TypeError:
        raise TypeError("heights must be an iterable of integers")

    n = len(heights)
    if n <= 1:
        return 0  # No one needs to leave for an empty or single-element list

    # Compute LIS lengths ending at each position (strictly increasing)
    lis_left = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis_left[j] + 1 > lis_left[i]:
                lis_left[i] = lis_left[j] + 1

    # Compute LIS lengths starting at each position in reversed order (strictly decreasing)
    lis_right = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lis_right[j] + 1 > lis_right[i]:
                lis_right[i] = lis_right[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis_left[i] + lis_right[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum deletions = total students - longest bitonic subsequence
    return n - max_bitonic

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list of tuples")
    for idx, record in enumerate(student_scores):
        if not (isinstance(record, tuple) and len(record) == 3):
            raise ValueError(f"Record at index {idx} is not a tuple of length 3")
        if not all(isinstance(x, int) for x in record):
            raise ValueError(f"All elements in record at index {idx} must be integers")
    return sorted(
        student_scores,
        key=lambda x: (-x[1], -x[2], x[0])
    )
